    private static void AddCreatureTypeSet(
        ref StateFingerprintBuilder fingerprint,
        char marker,
        ForkableSet<(Creature Owner, Type Type)>? values)
    {
        ulong first = 0;
        ulong second = 0;
        int count = 0;
