    private static void AddSteamEruptionPhases(
        ref StateFingerprintBuilder fingerprint,
        ForkableDictionary<Creature, SteamEruptionPhase>? values)
    {
        ulong first = 0;
        ulong second = 0;
        int count = 0;
        if (values != null)
        {
