    private sealed record StandPatRepeatValue(StandPatEvaluation Evaluation,object SolverOwner);
    private sealed class StandPatRepeatAudit
    {
        public System.Collections.Concurrent.ConcurrentDictionary<StandPatRepeatKey,StandPatRepeatValue> Values=new();
        public int Calls,Matches,WithinSolverMatches,CrossSolverMatches,Mismatches;
    }
    private static readonly System.Runtime.CompilerServices.ConditionalWeakTable<CombatRootSnapshot,StandPatRepeatAudit>
        StandPatRepeatAudits=new();
    private readonly object _standPatRepeatSolverOwner=new();
    private StandPatRepeatAudit _standPatRepeatAudit=StandPatRepeatAudits.GetValue(root,static _=>new());

    private void ObserveRepeatedStandPat(SearchNode node,StandPatEvaluation evaluation)
    {
        Interlocked.Increment(ref _standPatRepeatAudit.Calls);
        StandPatRepeatKey key=new(node.StateKey,_startTurnNumber,_potionPolicy,_forceAllPotionsDisabled,
            _minimumPotionUses,_maximumPotionUses,_enforcePotionDirectives,_includeTurnSetup,
            _run.InitialPersistentBuffValue,_run.InitialEnemyStrengthSuppression,
            _run.InitialEnemyWeakTurns,_run.InitialRetainedAttackValue);
        var proposed=new StandPatRepeatValue(evaluation,_standPatRepeatSolverOwner);
