from pathlib import Path
import hashlib,json

root=Path.cwd();task=root/'.local/tool-tasks/stand-pat-witness-observation-20261007'
paths=['src/Search/CombatBeamSolver.Retention.cs','src/Search/CombatBeamSolver.ParallelExpansion.cs','src/Search/CombatBeamSolver.Phases.cs']
def archive(path):return {'source':path.read_text(),'sha256':hashlib.sha256(path.read_bytes()).hexdigest()}
(task/'base-sources.json').write_text(json.dumps({p:archive(root/p) for p in paths},ensure_ascii=False,indent=2)+'\n')
p=root/paths[0];s=p.read_text();needle='''            ObserveSearchPath(node, SearchPathObservationStage.StandPatProbe, "stand_pat_replayed");'''
assert s.count(needle)==1
s=s.replace(needle,needle+'\n            ObserveWinningStandPat(node,end);',1)
needle='''    private StandPatEvaluation EvaluateStandPat(SearchNode node)''';assert s.count(needle)==1
helpers='''    private sealed class StandPatWitnessAudit
    {
        public readonly long Started = System.Diagnostics.Stopwatch.GetTimestamp();
        public int Probes;
        public System.Collections.Concurrent.ConcurrentQueue<object> Wins = new();
    }
    private StandPatWitnessAudit _standPatWitnessAudit = new();

    private void ObserveWinningStandPat(SearchNode parent,SimulationSnapshot end)
    {
        Interlocked.Increment(ref _standPatWitnessAudit.Probes);
        if(!end.AllEnemiesDead)return;
        int uses=ExplicitPotionUseCount(parent);
        bool complete=SolverInterimResultOrdering.IsCompleteVictory(parent.ActionCount+1,
            end.AllEnemiesDead,end.PlayerDead,end.ProjectedPlayerHp);
        bool hard=!end.HasRisk && end.BoundaryReason==SearchBoundaryReason.None
            && (!_enforcePotionDirectives || _potionStrategy.EvaluateForcedUses(
                parent.Actions,root.HasRenewablePotionShapedRock).AllForcedUsesSatisfied);
        int hp=ActEndingBossPolicy.StrategicHpDeficit(end.CumulativePlayerHpLost,
            Math.Max(0,root.InitialPlayerMaxHp-end.PlayerMaxHp),end.RecoveredPlayerHp
                +ActEndingBossPolicy.RankedPostCombatRelicHeal(root.PostCombatRelicHeal,true,
                    end.PlayerHp,end.PlayerMaxHp),_strategicBossHpRelief,end.DeathSaveHpRestored)
            -end.StrategicHpCredit;
        var bucket=ResourceIncumbentPolicy.CompletedBucket(end,uses);
        bool hasCurrent=_primaryIncumbents.TryGet(bucket,out var current);
        PrimarySearchIncumbent? proposed=hasCurrent?current:null;
        bool eligible=TryTightenPrimarySearchIncumbent(_potionFreePolicyBaseline,
            _minimumPotionUses,_maximumPotionUses,complete,hard,uses,hp,end.CombatEndedTurn,
            ref proposed,_potionPolicy,end.ProjectedDeathSaveUseCount,end.ExplicitPotionStrategicCost);
